/* ---------- Tool rail ---------- */
/* the Whiteboard template's tool rail (owner, 27 Nov): Canvas toolbar's bar stood on its end. One tool is picked at a time;
   the picked one sits on Canvas toolbar's soft accent tint (Clean: its one neutral selected fill), the others take the quiet
   hover. Its buttons do nothing else: what a tool does is the board's */
.tlr{display:flex;justify-content:center}
.tlr-bar{display:inline-flex;flex-direction:column;align-items:center;padding:var(--dm-s-1);border-radius:var(--dm-r-pill);background:var(--dm-raised);box-shadow:var(--dm-shadow-pop)}
.tlr-bar :focus-visible{border-radius:var(--dm-r-pill)}
.tlr-tools{display:flex;flex-direction:column;align-items:center}
.tlr-b{width:32px;height:32px;flex:none;display:grid;place-items:center;border-radius:var(--dm-r-pill);color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.tlr-b:hover{background:var(--dm-row);color:var(--dm-fg)}}
.tlr-b[aria-checked="true"]{background:color-mix(in srgb,var(--dm-accent) 12%,transparent);color:var(--dm-accent-fg)}
@media (hover:hover) and (pointer:fine){.tlr-b[aria-checked="true"]:hover{background:color-mix(in srgb,var(--dm-accent) 12%,transparent);color:var(--dm-accent-fg)}}
.tlr-sep{width:16px;height:1px;margin:var(--dm-s-1) auto;flex:none;background:var(--dm-line)}
/* Clean's picked tool is its one selected fill, neutral, never a hue (as on the Whiteboard) */
:root[data-style="clean"] .tlr-b[aria-checked="true"],:root [data-style="clean"] .tlr-b[aria-checked="true"],:root [data-style="clean"].tlr-b[aria-checked="true"]{background:var(--dm-row-on);color:var(--dm-fg)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .tlr-b[aria-checked="true"]:hover,:root [data-style="clean"] .tlr-b[aria-checked="true"]:hover,:root [data-style="clean"].tlr-b[aria-checked="true"]:hover{background:var(--dm-row-on);color:var(--dm-fg)}}

DM.def('tool-rail', (r, c) => {
  r.innerHTML = r.innerHTML.replace(/\{([\w-]+)\}/g, (m, k) => I(k));
  const bs = $$('.tlr-b', r), keys = Object.fromEntries(bs.map(b => [b.dataset.tipK.toLowerCase(), b]));
  // one tool at a time, like radio buttons: the picked one is checked and is the one Tab stops on
  const pick = b => bs.forEach(x => { const on = x === b; x.setAttribute('aria-checked', String(on)); x.tabIndex = on ? 0 : -1; });
  bs.forEach(b => c.on(b, 'click', () => pick(b)));
  // the arrows move the pick along the rail, and a tool's letter picks it, while the focus is in the rail
  c.on($('.tlr-bar', r), 'keydown', e => {
    const d = { ArrowDown:1, ArrowRight:1, ArrowUp:-1, ArrowLeft:-1 }[e.key];
    const n = d ? bs[(bs.indexOf(document.activeElement) + d + bs.length) % bs.length] : !e.metaKey && !e.ctrlKey && !e.altKey && keys[e.key.toLowerCase()];
    if (!n) return; e.preventDefault(); pick(n); n.focus();
  });
  // the preview's story: try the pen, a sticky note and a comment, then back to Select
  const t = k => $(`.tlr-b[data-t="${k}"]`, r);
  c.story(async s => {
    await s.beat(2);
    await s.point(t('pen')); await s.beat(1.5); await s.tap(t('pen')); await s.beat(2.5);
    await s.point(t('sticky')); await s.beat(1.5); await s.tap(t('sticky')); await s.beat(2.5);
    await s.tap(t('comment')); await s.beat(2.5);
    await s.tap(t('select')); s.away(); await s.beat(2);
  });
});
